"""Append C214 (idempotent): the trend log holds two different bands, and within the right one the decay is slowing."""
import io, os

p = r'D:\kaggle\rsna-knee\state\FACTS.md'
ADD = """| C214 | 📈🔧 **【趋势日志里混着【两个档】,而按正确的那个档拆开之后:档位膨胀在【减速】、余量衰减也在【减速】⇒ 截止时我们应比先前估计的位置更好】** `work/band_growth.py` 对 `state/daily_trend.jsonl` 的 **35 次读数**做了按档拆分。<br>**① 我先前一直没注意的污染**：那份日志里 **10-16 之前是我们持 0.956 时的档、之后才是 0.958 的档**（10-16 12:42 那次是换档后的第一次读数）。⇒ **任何跨这个断点的"档增长速率"都在混合两个不同的人群** —— 包括我 C208/C210 里用过的那些速率。<br>**② 0.958 档内部（23 次读数,10-16 12:42 → 10-22 00:34）**：<br>· **档增长：前半 10.25 队/小时 → 后半 4.73 队/小时 ⇒【减速】**（新队伍迁入同一档的速度在下降）;<br>· **铜线余量：+377 → +61（132 小时）⇒ −2.40/小时**;<br>· **但最近 15 小时只有 −1.23/小时**（10-21 09:55 的 +79 → 10-22 00:34 的 +61）。<br>**③ ⇒ 截止时（23.4 小时后）的区间**：<br>· 用**全档速率** −2.40/h ⇒ 余量 **≈ +5**（贴着线）;<br>· 用**最近速率** −1.23/h ⇒ 余量 **≈ +32**（在内）;<br>**因为档增长本身在减速（②的第一条），近期速率是更好的预测器 ⇒ 更可能落在 +15 到 +32 之间。**<br>**④ 档内位置**：145（10-13）→ 336（10-22 的 0.958 档内）。**这个数变差是因为档在填充,而不只是档在变大** —— 而填充在减速。<br>**⑤ 方法论（第三次同类,但这次抓的是自己的历史文件）**：**先把"序列里换了总体没有"这件事查一遍,再算速率。** C210 我修了"滑动窗口选错",C214 修的是更隐蔽的一种:**窗口本身没错,但序列中途换过总体（换档）**。⇒ 现在这条链上是"指标噪声 > 效应"(C206) → "窗口跨加速期"(C210) → "序列跨总体换档"(C214)。 | 2026-10-22 |
"""
txt = io.open(p, encoding='utf-8').read()
if '| C214 |' in txt:
    raise SystemExit('REFUSING: C214 already present')
with io.open(p, 'a', encoding='utf-8') as fh:
    fh.write(ADD)
print('appended C214; file now', os.path.getsize(p), 'bytes')
